DROP TABLE IF EXISTS `inventory_material`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventory_material` (
  `material_id` bigint NOT NULL AUTO_INCREMENT COMMENT '物料ID',
  `product_id` bigint DEFAULT NULL COMMENT '关联产品ID(成品物料)',
  `material_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '物料编码',
  `material_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '物料名称',
  `material_meta` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料材质',
  `process_group` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'M' COMMENT 'M面板,U上线,D下线,T弹片,S导光片,K扩散片,O其他',
  `category_id` bigint DEFAULT NULL COMMENT '物料分类ID',
  `specification` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规格型号/技术参数',
  `width_mm` decimal(10,2) DEFAULT NULL COMMENT '宽(mm)：尺寸数值真源之一',
  `length_mm` decimal(12,2) DEFAULT NULL COMMENT '长(mm)：卷料为展开长度，片材为边长',
  `thickness_mm` decimal(10,4) DEFAULT NULL COMMENT '厚(mm)：spec_basis=THICKNESS 时必填',
  `grammage` decimal(10,2) DEFAULT NULL COMMENT '克重 g/m²：spec_basis=GRAMMAGE 时必填',
  `thickness_tolerance` decimal(10,4) DEFAULT NULL COMMENT '厚度公差 ±mm',
  `size_unit` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'mm' COMMENT '尺寸单位，显式声明，不做缺省推断',
  `spec_basis` varchar(12) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SIZE' COMMENT '规格口径：THICKNESS/GRAMMAGE/SIZE',
  `material_grade` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '材料：含形态的受控复合词，如PE保护膜/PC膜/EVA泡棉',
  `model` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '型号/料号/规格档（3M5604、PET125#、M1.6*3）',
  `color` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '颜色（透明/白色/黑色/黄色/红色/蓝色/灰色/银色）',
  `brand` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '品牌（与供应商区分）',
  `search_keywords` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '别名/客户叫法，逗号分隔',
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'PCS' COMMENT '基本计量单位',
  `unit_conv` decimal(10,4) DEFAULT NULL COMMENT '换算系数（辅助单位与基本单位的换算）',
  `unit_alt` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '辅助计量单位',
  `batch_control` tinyint(1) DEFAULT '0' COMMENT '是否启用批次管理：0否 1是',
  `shelf_life` int DEFAULT NULL COMMENT '保质期天数',
  `expiry_alert_days` int DEFAULT '30' COMMENT '保质期预警提前天数',
  `safe_stock` decimal(12,4) DEFAULT '0.0000' COMMENT '安全库存数量',
  `max_stock` decimal(12,4) DEFAULT '0.0000' COMMENT '最高库存数量',
  `reorder_point` decimal(12,4) DEFAULT '0.0000' COMMENT '再订货点',
  `standard_price` decimal(12,4) DEFAULT NULL COMMENT '标准采购单价',
  `cost_price` decimal(12,4) DEFAULT NULL COMMENT '成本单价(人定,099)',
  `lead_time` int DEFAULT NULL COMMENT '采购提前期(天)',
  `supplier_id` bigint DEFAULT NULL COMMENT '主要供应商ID',
  `supplier_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主要供应商名称',
  `supplier_material_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商侧品名/叫法（采购单与来料核对用）',
  `default_warehouse_id` bigint DEFAULT NULL COMMENT '默认仓库ID',
  `default_location_id` bigint DEFAULT NULL COMMENT '默认库位ID',
  `status` tinyint DEFAULT '1' COMMENT '物料状态：1启用/0停用/2废弃',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注（含原名称/原规格留痕）',
  `search_blob` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS (left(concat_ws(_utf8mb4' ',ifnull(`material_name`,_utf8mb4''),ifnull(`material_code`,_utf8mb4''),ifnull(`model`,_utf8mb4''),ifnull(`material_grade`,_utf8mb4''),ifnull(`color`,_utf8mb4''),ifnull(`specification`,_utf8mb4''),ifnull(`search_keywords`,_utf8mb4''),ifnull((case when ((`width_mm` is null) and (`length_mm` is null) and (`thickness_mm` is null)) then NULL else concat(ifnull(trim(trailing _utf8mb4'.' from trim(trailing _utf8mb4'0' from cast(`width_mm` as char charset utf8mb4))),_utf8mb4''),if(((`length_mm` is not null) or (`thickness_mm` is not null)),concat(_utf8mb4'*',ifnull(trim(trailing _utf8mb4'.' from trim(trailing _utf8mb4'0' from cast(`length_mm` as char charset utf8mb4))),_utf8mb4'')),_utf8mb4''),if((`thickness_mm` is not null),concat(_utf8mb4'*',ifnull(trim(trailing _utf8mb4'.' from trim(trailing _utf8mb4'0' from cast(`thickness_mm` as char charset utf8mb4))),_utf8mb4'')),_utf8mb4''),`size_unit`) end),_utf8mb4''),ifnull(`brand`,_utf8mb4''),ifnull(`supplier_material_name`,_utf8mb4''),ifnull(nullif(trim(replace(replace(replace(replace(replace(ifnull(`attribute_json`,_utf8mb4''),_utf8mb4'"',_utf8mb4''),_utf8mb4'{',_utf8mb4''),_utf8mb4'}',_utf8mb4''),_utf8mb4',',_utf8mb4' '),_utf8mb4':',_utf8mb4' ')),_utf8mb4''),_utf8mb4'')),1000)) STORED,
  `material_form` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '形态代码，引用form字典',
  `attribute_json` json DEFAULT NULL COMMENT '按末级品类模板校验的属性值，唯一属性真源',
  `is_customer_supplied` tinyint NOT NULL DEFAULT '0' COMMENT '客供专用档案标记，不表达批次所有权',
  `is_sample` tinyint NOT NULL DEFAULT '0' COMMENT '样品专用档案标记，不表达某次用途',
  `template_id` bigint DEFAULT NULL COMMENT '属性模板；由属性保存入口同源写入',
  `attr_meta` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when (json_type(json_extract(`attribute_json`,_utf8mb4'$.material')) = _utf8mb4'STRING') then json_unquote(json_extract(`attribute_json`,_utf8mb4'$.material')) else NULL end)) STORED,
  `class_source` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'RULE/MANUAL/IMPORT，为空表示未归类',
  `class_confirmed` tinyint(1) NOT NULL DEFAULT '0' COMMENT '人工确认标记',
  PRIMARY KEY (`material_id`),
  UNIQUE KEY `uk_material_code` (`material_code`),
  KEY `idx_category_id` (`category_id`),
  KEY `idx_status` (`status`),
  KEY `idx_material_name` (`material_name`),
  KEY `idx_material_grade` (`material_grade`),
  KEY `idx_model` (`model`),
  KEY `idx_color` (`color`),
  KEY `idx_brand` (`brand`),
  KEY `idx_search_blob` (`search_blob`(768)),
  KEY `idx_material_template` (`template_id`),
  KEY `idx_material_attr_meta` (`attr_meta`),
  KEY `idx_material_classify` (`class_source`,`class_confirmed`),
  CONSTRAINT `fk_material_category` FOREIGN KEY (`category_id`) REFERENCES `inventory_material_category` (`category_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_material_template` FOREIGN KEY (`template_id`) REFERENCES `inventory_attribute_template` (`template_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=349 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='物料主表';
